ee:message.ee:set-payload:
%dw 2.0
output application/json
var config = vars.llmConfig
var promptContent = vars.enrichedPrompt default "Generate mapping documentation based on the provided input and output examples."
---
{
	contents: [
		{
			parts: [
				{
					text: "You are an expert data mapping analyst. " ++ promptContent ++ "\n\nPlease respond with valid JSON only."
				}
			]
		}
	],
	generationConfig: {
		temperature: config.temperature,
		maxOutputTokens: config.maxTokens,
		responseMimeType: "application/json"
	}
}
